+    // After both moves (user + agent), re-enable user input if game not over
+    if (!data.done) {
+      setTimeout(() => {
+        setUserTurn(true);
+      }, 500); // Small delay for UX
+    }
+  };
+
+  // Score the game after it ends
+  const scoreGame = async () => {
