+import { formatDuration, handleSpotifyRequest } from './utils.js';
+
+function isTrack(item: any): item is SpotifyTrack {
+  return (
+    item &&
+    item.type === 'track' &&
+    Array.isArray(item.artists) &&
+    item.album &&
+    typeof item.album.name === 'string'
+  );
+}
