+    sum = 0;
+  }
+  int getSum(Node *v) { return (v ? v->sum : 0); }
+  void update() { this->sum = getSum(this->left) + getSum(this->right); }
+  Node(Node *l, Node *r) {
+    left = l;
+    right = r;
+    sum = getSum(left) + getSum(right);
