+four take_seg(int i) {
+  four f = *(--se.upper_bound(four(i)));
+  se.erase(f);
+  if (!(--ma[f.f()])) ma.erase(f.f());
+  return f;
+}
+void push_seg(four f) {
+  if (f.f()) {
+    se.insert(f);
+    ++ma[f.f()];
+  }
+}
