+        self.q_max = q_max
+
+    def _build_tree(self, n):
+        parent_map = {1: None}
+        for i in range(2, n+1):
+            parent_map[i] = random.randint(1, i-1)
+        return [parent_map[i] for i in range(2, n+1)], parent_map
+
+    @staticmethod
+    def _find_lca(u, v, parent_map):
+        path = set()
+        while u:
+            path.add(u)
+            u = parent_map.get(u)
+        while v not in path:
+            v = parent_map.get(v)
+        return v
+
+    def _calc_mex(self, n, p, parent_map):
+        max_mex = 0
+        for start in range(1, n+1):
+            for end in range(start, n+1):
+                path = set()
+                current = start
+                lca = self._find_lca(start, end, parent_map)
+                
+                while current != lca:
+                    path.add(current)
+                    current = parent_map[current]
+                path.add(lca)
+                
+                current = end
+                while current != lca:
+                    path.add(current)
+                    current = parent_map[current]
+                
+                values = {p[node-1] for node in path}
+                mex = 0
+                while mex in values:
+                    mex += 1
+                max_mex = max(max_mex, mex)
+        return max_mex
+
+    def case_generator(self):
